let ok=function Ok x->x|Error _->failwith"error"
let ()=let a=ok(Raster2.Scratch.create~initial_capacity:0~hard_capacity:1024)in let s=ok(Raster2.Scratch.reserve a~alignment:16~length:17)in if Raster2.Scratch.slice_offset s<>0 then failwith"alignment";Raster2.Scratch.fill s 'x';ignore(ok(Raster2.Scratch.set s 16 'y'));if Raster2.Scratch.snapshot s<>Bytes.of_string"xxxxxxxxxxxxxxxxy"then failwith"contents";Raster2.Scratch.reset a;(match Raster2.Scratch.get s 0 with Error Raster2.Scratch.Invalid_reservation->()|_->failwith"stale slice");for _=1 to 100000 do let x=ok(Raster2.Scratch.reserve a~alignment:64~length:513)in Raster2.Scratch.fill x 'z';Raster2.Scratch.reset a done;let m=Raster2.Scratch.metrics a in if m.capacity<>1024||m.used<>0||m.high_water<>513||m.growths>2 then failwith"plateau";(match Raster2.Scratch.reserve a~alignment:1~length:1025 with Error Raster2.Scratch.Capacity_exceeded->()|_->failwith"capacity");let run()=let x=ok(Raster2.Scratch.create~initial_capacity:1~hard_capacity:128)in for n=1 to 50 do ignore(ok(Raster2.Scratch.reserve x~alignment:8~length:(n mod 7)));if n mod 5=0 then Raster2.Scratch.reset x done;Raster2.Scratch.metrics x in let expected=run()in let ws=Array.init 4(fun _->Domain.spawn run)in Array.iter(fun w->if Domain.join w<>expected then failwith"domain")ws;print_endline"Raster2 bounded scratch arena passed"
